package com.acaivis.controller; import com.acaivis.dto.*; import com.acaivis.service.CategoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController {private final CategoryService s;public CategoryController(CategoryService s){this.s=s;} @GetMapping public List<CategoryResponse> all(){return s.findAll();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public CategoryResponse create(@Valid @RequestBody CategoryRequest d){return s.create(d);} @PutMapping("/{id}") public CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest d){return s.update(id,d);} @PatchMapping("/{id}/reactivate") public CategoryResponse reactivate(@PathVariable Long id){return s.reactivate(id);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
